"""Make the optional offline Dutch step viewer from the actual numbered HD
shutters written by ASCOT_DEMO in tests/diagonal.browser.cjs. No new artwork.
Usage: python tools/trot_view.py sideroll.webp drafstudie.html
"""
import base64,sys,subprocess
from pathlib import Path
from PIL import Image
photo=Path(sys.argv[1]);source=Image.open(photo);cw,ch=source.width//6,source.height//2
assert (cw,ch) in ((248,198),(308,245)) and source.size==(cw*6,ch*2) and source.format=='WEBP'
# The HD drawCast shutter is already a finished photograph. Keep its native
# pixels and bytes; do not rescale/recompress before magnifying the leg.
uri='data:image/webp;base64,'+base64.b64encode(photo.read_bytes()).decode()
page='''<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Royal Ascot · Drafstudie</title><style>
:root{color-scheme:light;--pine:#15392d;--paper:#f5f1e7;--ochre:#e4bd75;--rule:#ccc8b9}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:#1b3027;font:16px/1.45 system-ui,sans-serif}main{width:min(816px,100%);padding:clamp(14px,4vw,40px);margin:auto}header,footer{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid var(--rule);padding:9px 0;color:#4b5c50;font-size:.68rem;letter-spacing:.13em;text-transform:uppercase;font-weight:700}.flag{display:inline-block;width:10px;height:10px;background:var(--pine);margin-right:9px;transform:rotate(45deg)}h1{font:normal clamp(36px,6vw,57px)/1.05 Georgia,serif;margin:22px 0 5px;letter-spacing:-.035em}p{margin:0 0 16px;color:#43584c}figure{position:relative;margin:0;overflow:hidden;border:1px solid #506858;border-radius:5px;background:radial-gradient(ellipse at 50% 26%,#79927f,#4b6756 60%,#385446);box-shadow:inset 0 0 44px #102e242b}.corner{position:absolute;left:12px;top:9px;color:#e0e8d8;font:600 10px/1.2 ui-monospace,monospace;letter-spacing:.12em}canvas{display:block;width:min(96%,550px);height:auto;margin:5px auto 0}.status{margin:0;background:var(--pine);color:#f4eedf;border:1px solid #163c2d;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;gap:8px}.status strong{font:normal clamp(17px,4vw,24px)/1.2 Georgia,serif}.status span{font:12px ui-monospace,monospace;color:var(--ochre);white-space:nowrap}.frames{margin:16px 0 9px;display:grid;grid-template-columns:repeat(12,1fr);gap:3px}.frames button{padding:8px 0;border-radius:2px;color:#4b5950;background:#e4e5dc;border:1px solid transparent;line-height:1}.frames .air{background:#edddbb}.frames [aria-pressed=true]{color:white;background:var(--pine);border-color:var(--pine)}.controls{display:flex;gap:6px;align-items:center;flex-wrap:wrap}button,select{min-height:39px;background:transparent;border:1px solid #a5ad9c;border-radius:4px;color:var(--pine);font:600 14px system-ui;padding:8px 12px;cursor:pointer}#play{background:var(--pine);color:white;min-width:87px}button:hover,select:hover{border-color:var(--pine)}#marks[aria-pressed=true]{background:#dce5d9}button:focus-visible,select:focus-visible{outline:3px solid #b56a22;outline-offset:2px}.controls label{margin-left:auto}.trace{margin:14px 0 0;display:flex;gap:8px 12px;align-items:center;flex-wrap:wrap}.trace label,.key{font-size:13px}.key{display:inline-flex;align-items:center;gap:6px}.key i{width:12px;height:12px;border-radius:50%;border:1.5px solid #274738;background:#ffda87}.key.h i{background:#81ebe1}.trace select{min-height:38px}aside{border-top:1px solid var(--rule);margin-top:18px;padding-top:12px;font-size:.9rem;color:#42574a}aside b{color:var(--pine)}footer{border:0;margin-top:5px;font-size:9px} @media(max-width:420px){.controls label{margin-left:0}.frames button{font-size:12px} .corner{font-size:9px}} @media(max-height:520px) and (min-width:650px){main{padding:8px 22px}h1{margin:8px 0 3px;font-size:32px}canvas{width:210px}p{margin-bottom:6px}.frames{margin:6px 0}.status{padding:5px 12px}aside{margin-top:6px}}
</style><main><header><div><i class="flag"></i>Royal Ascot</div><div>Sulky · Bewegingsstudie 04</div></header><h1>De hoge knie in draf.</h1><p>De neus wijst naar rechts. Kijk naar de hoge knie (K): die vouwt naar voren bij het optillen. De lagere sprong (S) knikt naar de staart. Vergelijk beeld 6, 8 en 11, of kies het andere achterbeen.</p><figure><span class="corner" id="shot">ZIJCAMERA &nbsp;/&nbsp; SULKY 04 · NEUS →</span><canvas id="screen" width="432" height="344" aria-label="Paard vier in draf, gezien vanaf de rechterflank"></canvas></figure><div class="status"><strong id="pair">Linksvoor + rechtsachter</strong><span id="counter">01 / 12</span></div><nav class="frames" aria-label="Kies een van de twaalf beelden"></nav><div class="controls"><button type="button" id="play">Pauze</button><button id="prev" aria-label="Vorig beeld" title="Vorig beeld">←</button><button id="next" aria-label="Volgend beeld" title="Volgend beeld">→</button><button id="marks" aria-pressed="true" title="Toon of verberg de gemeten hoefposities">Hoefmarkeringen</button><label><select id="rate" aria-label="Afspeeltempo"><option value="2400">Vertraagd · 2,4 s</option><option value="1200">Studietempo · 1,2 s</option><option value="600">Vlot · 0,6 s</option></select></label></div><div class="trace"><label for="hind">Volg het achterbeen</label> <select id="hind"><option value="0">Rechtsachter</option><option value="1">Linksachter</option><option value="off">Zonder hulplijn</option></select><button id="zoom" type="button" aria-pressed="false">Knie vergroten</button><span class="key"><i></i> K · Knie</span><span class="key h"><i></i> S · Sprong</span></div><aside><b id="moment">Landing.</b> <span id="lesson"></span> <span id="foldnote"></span></aside><footer><span>12 originele koersbeelden</span><span>Vertraagde weergave</span></footer></main><script>
const $=s=>document.querySelector(s),pic=new Image(),ctx=$('#screen').getContext('2d'),pair=$('#pair'),counter=$('#counter'),play=$('#play'),rate=$('#rate'),keys=[];const toes=TOES;const jointTracks=JOINTS;let zoom=false,marked=true,ph=0,run=!matchMedia('(prefers-reduced-motion: reduce)').matches,base=0;const pairAt=n=>n%6===5?'Zweefmoment':n<6?'Linksvoor + rechtsachter':'Rechtsvoor + linksachter';for(let i=0;i<12;i++){const e=document.createElement('button');e.textContent=i+1;e.className=i%6===5?'air':'';e.setAttribute('aria-label',`Beeld ${i+1}: ${pairAt(i)}`);e.onclick=()=>select(i);$('.frames').append(e);keys.push(e)}function traceHind(){const target=$('#hind').value;if(target==='off')return;const leg=jointTracks[ph][Number(target)].map(([x,y])=>[432*x,344*y]);ctx.save();ctx.lineJoin='round';ctx.lineCap='round';if(target==='1')ctx.setLineDash([4,3]);ctx.beginPath();leg.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.lineWidth=3.8;ctx.strokeStyle='rgba(15,39,31,.68)';ctx.stroke();ctx.lineWidth=1.25;ctx.strokeStyle='#fff6da';ctx.stroke();ctx.setLineDash([]);for(const [i,color] of [[1,'#ffda87'],[2,'#81ebe1']]){const [x,y]=leg[i];ctx.beginPath();ctx.arc(x,y,3.75,0,2*Math.PI);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#193a2e';ctx.lineWidth=1.25;ctx.stroke();ctx.font='bold 10px system-ui';ctx.textBaseline='middle';ctx.textAlign='center';const tx=x+(i===1?10:-10);ctx.fillStyle='#15392d';ctx.fillRect(tx-5,y-6,10,12);ctx.fillStyle=color;ctx.fillText(i===1?'K':'S',tx,y)}ctx.restore()}
function show(){if(pic.naturalWidth){ctx.clearRect(0,0,432,344);ctx.save();if(zoom){ctx.translate(216,172);ctx.scale(1.92,1.92);ctx.translate(-.468*432,-.605*344);}ctx.imageSmoothingQuality='high';ctx.drawImage(pic,ph%6*pic.naturalWidth/6,Math.floor(ph/6)*pic.naturalHeight/2,pic.naturalWidth/6,pic.naturalHeight/2,0,0,432,344);traceHind();if(marked){const air=ph%6===5,feet=air?[0,1,2,3]:ph<6?[0,3]:[1,2];for(const j of feet){const [u,v]=toes[ph][j],x=u*432,y=v*344;ctx.lineWidth=1.7;ctx.strokeStyle=air?'#f6e7c0':'#f6d193';ctx.beginPath();ctx.arc(x,y,air?4:3,0,2*Math.PI);ctx.stroke();if(!air){ctx.beginPath();ctx.moveTo(x,y+4);ctx.lineTo(x,y+9);ctx.stroke();ctx.fillStyle='#193a2e';ctx.fillRect(x-11,y+9,22,14);ctx.textAlign='center';ctx.font='bold 10px system-ui';ctx.fillStyle='#ffe3a7';ctx.fillText(['RA','LA','RV','LV'][j],x,y+19)}}}ctx.restore()}counter.textContent=String(ph+1).padStart(2,'0')+' / 12';pair.textContent=pairAt(ph);const phase=ph%6;$('#moment').textContent=['Landing.','Gewicht opnemen.','Middensteun.','Terugveren.','Over de teen.','Zweefmoment.'][phase];$('#lesson').textContent=['De diagonale hoeven raken de baan.','De kogel zakt terwijl de hoef vlak blijft.','De romp staat lager boven het dragende beenpaar.','De kogel veert terug, vóór de hoef loskomt.','De hiel komt omhoog; de teen houdt nog contact met de baan.','De ene diagonaal heeft afgezet; de andere bereidt de landing voor.'][phase];keys.forEach((k,i)=>k.setAttribute('aria-pressed',String(i===ph)));const target=$('#hind').value;$('#foldnote').textContent=target==='off'?'De gewrichtslijn is uit. Zet ook de hoefmarkeringen uit voor het oorspronkelijke spelbeeld.':(target==='1'?'De stippellijn volgt het verre achterbeen, ook waar het schuilgaat. ':'')+'Geel is de hoge knie; de blauwe stip volgt het lager gelegen spronggewricht.';play.textContent=run?'Pauze':'Afspelen'}function select(n){run=false;ph=(n+12)%12;show()}$('#prev').onclick=()=>select(ph-1);$('#next').onclick=()=>select(ph+1);function toggle(){run=!run;base=performance.now()-ph*rate.value/12;show()}play.onclick=toggle;$('#hind').onchange=show;$('#zoom').onclick=()=>{zoom=!zoom;$('#zoom').setAttribute('aria-pressed',String(zoom));$('#zoom').textContent=zoom?'Hele aanspanning':'Knie vergroten';$('#shot').textContent=zoom?'DETAIL / ACHTERBEEN · NEUS →':'ZIJCAMERA / SULKY 04 · NEUS →';show();};$('#marks').onclick=()=>{marked=!marked;$('#marks').setAttribute('aria-pressed',String(marked));show()};rate.onchange=()=>base=performance.now()-ph*rate.value/12;document.onvisibilitychange=()=>base=performance.now()-ph*rate.value/12;document.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();select(ph+(e.key==='ArrowRight'?1:-1))}});function anim(t){if(run&&!document.hidden){const p=Math.floor((t-base)*12/rate.value+12)%12;if(p!==ph){ph=p;show()}}requestAnimationFrame(anim)}pic.onload=()=>{base=performance.now();show();requestAnimationFrame(anim)};pic.src='STOCK';show();</script></html>'''
marks=subprocess.check_output(['node',str(Path(__file__).with_name('hoof_marks.cjs'))],text=True).strip()
joints=subprocess.check_output(['node',str(Path(__file__).with_name('hind_marks.cjs'))],text=True).strip()
# Replace complete template statements, never bare words inside the encoded photograph.
page=page.replace('const toes=TOES;', 'const toes='+marks+';',1).replace('const jointTracks=JOINTS;', 'const jointTracks='+joints+';',1).replace("pic.src='STOCK';", "pic.src='"+uri+"';",1)
assert "pic.src='"+uri+"';" in page
Path(sys.argv[2]).write_text(page);print('Self-contained measured side view:',Path(sys.argv[2]).stat().st_size,'bytes')
